from pathlib import Path
import re,json,html
root=Path(__file__).resolve().parents[1]; base='/examples/plumbing/'
org=re.search(r'<!-- ICEWIND:ORGANIZATION-SCHEMA:START -->.*?<!-- ICEWIND:ORGANIZATION-SCHEMA:END -->',(root/'index.html').read_text(),re.S).group()
icon='<svg viewBox="0 0 36 42" aria-hidden="true" fill="none"><path d="M18 3C14 10 5 18 5 26a13 13 0 0 0 26 0C31 18 22 10 18 3Z" stroke="currentColor" stroke-width="2.4"/><path d="M12 27a6 6 0 0 0 6 6" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg>'
urls={'home':'','about':'about/','services':'services/','leak-repairs':'leak-repairs/','taps-and-toilets':'taps-and-toilets/','bathroom-plumbing':'bathroom-plumbing/','areas':'areas/','faq':'faq/','contact':'contact/','privacy':'privacy/'}
names={'home':'Home','about':'About us','services':'Our services','leak-repairs':'Leaks & repairs','taps-and-toilets':'Taps & toilets','bathroom-plumbing':'Bathroom plumbing','areas':'Areas we cover','faq':'Common questions','contact':'Get in touch','privacy':'Privacy & demo information'}
def link(key,text=None,cls=''):return f'<a class="{cls}" href="{base+urls[key]}">{text or names[key]}</a>'
def cards():
 return '<div class="service-cards">'+''.join(f'<a href="{base+urls[k]}"><span class="card-number">0{i}</span><h3>{title} <span>↗</span></h3><p>{copy}</p><span class="card-link">How we can help →</span></a>' for i,(k,title,copy) in enumerate([('leak-repairs','Leaks & repairs','A damp patch, a dripping pipe or a leak that needs a closer look. Get the cause checked and the repair explained.'),('taps-and-toilets','Taps & toilets','Dripping taps, toilets that keep running and tired fittings ready for a replacement.'),('bathroom-plumbing','Bathroom plumbing','Practical plumbing help for a bathroom refresh, from replacing fittings to planning pipework.')],1))+'</div>'
def cta():return '<section class="cta"><div class="container"><div><span class="eyebrow">A good place to start</span><h2>Tell us what<br>needs sorting.</h2></div><div><p>A short description and your postcode help us understand the job. We can discuss the next step from there.</p>'+link('contact','Describe your job <span>↗</span>','button light')+'</div></div></section>'
def steps():return '<div class="steps">'+''.join(f'<article><span>0{i}</span><h3>{h}</h3><p>{p}</p></article>' for i,(h,p) in enumerate([('Tell us about it','Share the issue, your postcode and a convenient way to get back to you.'),('Agree the next step','We discuss the job, check availability and explain the likely work before a visit.'),('Get it sorted','We explain what needs doing and agree any changes before going ahead.')],1))+'</div>'
def intro(label,title,copy):return f'<section class="page-intro container"><p class="eyebrow">{label}</p><h1>{title}</h1><p class="lead">{copy}</p></section>'
faq=[('What information should I send?','A short description of the problem and your postcode are a useful start. If you know the make of a fitting or where a leak is coming from, include that too.'),('Can I get a quote before work starts?','Tell us about the job first. Some work can be discussed from a description; other problems need an inspection before the scope and price can be agreed.'),('Do you cover my area?','This example shows a local service area in south-west London. On a real website, the coverage list would reflect the business’s actual working area.'),('Can I supply my own taps or bathroom fittings?','Mention that when you enquire. Compatibility, access and the condition of existing pipework need to be checked before installation is agreed.'),('Do you carry out gas or boiler work?','Gas and boiler services are not advertised in this example. A real business should only list work it is qualified and registered to carry out.'),('Can I book a visit online?','The enquiry form is a request to discuss a job, not a confirmed booking. A real business would get back to you to agree a visit.'),('What happens if the job changes?','Any additional work or parts should be explained and agreed before the work goes ahead.'),('Is this a real plumbing company?','No. Alder & Flow is a fictional business created by ICE WIND to demonstrate a ten-page website. Forms, phone and WhatsApp buttons do not contact a plumber.')]
def faqs(rows=faq):return '<div class="faqs">'+''.join(f'<details><summary>{q}<span>+</span></summary><p>{a}</p></details>' for q,a in rows)+'</div>'
pages={}
pages['home']=('Local plumbing, thoughtfully done.','A ten-page example of a local plumbing website, created by ICE WIND.',f'''<section class="hero container"><div class="hero-copy"><p class="eyebrow"><span class="live-dot"></span> Domestic plumbing · South-west London</p><h1>Small leaks.<br>Big plans.<br><em>Sorted.</em></h1><p class="lead">Practical plumbing help for the home. From a tap that won’t stop dripping to the bathroom you’ve been planning.</p><div class="actions">{link('contact','Tell us about your job <span>↗</span>','button')}{link('services','Explore our services →','text-link')}</div><div class="hero-foot"><span>Clear communication</span><span>Work agreed before we start</span></div></div><figure class="hero-image"><img src="/assets/offer-demo/bathroom.jpg" width="1200" height="1600" fetchpriority="high" alt="A bathroom basin with a brass tap, marble surface and leafy green plant"><figcaption><span>Good plumbing.<br>A home that works.</span><span class="image-arrow">↗</span></figcaption></figure></section><section class="service-section container"><div class="section-heading"><div><p class="eyebrow">What we do</p><h2>A little help.<br>A better home.</h2></div><p>Useful advice and practical repairs.<br>Start with the job you have in mind.</p></div>{cards()}</section><section class="approach container"><div class="approach-image"><img src="/assets/offer-demo/bathroom.jpg" loading="lazy" width="900" height="750" alt="Bathroom fittings and a neatly finished basin"></div><div class="approach-copy"><p class="eyebrow">A straightforward approach</p><h2>Your home.<br>Our attention.</h2><p>Plumbing work starts with listening. What is happening, what has changed, and what do you need the space to do?</p><p>We talk through the next step, explain the work and agree the scope before getting started.</p>{link('about','A little about us →','text-link')}</div></section><section class="how container"><div class="section-heading"><div><p class="eyebrow">From first message to finished job</p><h2>Let’s keep it simple.</h2></div></div>{steps()}</section><section class="area-strip container"><div><p class="eyebrow">Close to home</p><h2>Local help,<br>across south-west London.</h2></div><div><p>Wimbledon · Raynes Park · Morden<br>New Malden · Kingston · Surbiton</p>{link('areas','Check the example service area →','text-link')}</div></section><section class="container questions"><div class="section-heading"><div><p class="eyebrow">Before you get in touch</p><h2>A few useful answers.</h2></div>{link('faq','All questions →','text-link')}</div>{faqs(faq[:3])}</section>{cta()}''')
pages['about']=('A practical approach to your home.','Meet the approach behind this fictional local plumbing business.',intro('About Alder & Flow','Good work starts<br>with a conversation.','A local plumbing business, built around the everyday jobs that keep a home running.')+'''<section class="container editorial"><div><h2>The job matters.<br>So does the way<br>it gets done.</h2></div><div><p>When something stops working at home, you need to understand what happens next. We make room for questions, explain the options and agree the work before starting.</p><p>That applies to a small repair just as much as a planned bathroom update. The aim is a clear scope, careful work and a useful explanation of what has been done.</p><div class="principles"><article><h3>Listen first</h3><p>A clear description helps us focus on the problem rather than make assumptions.</p></article><article><h3>Explain the options</h3><p>Repairs and replacements can involve different choices. We talk them through.</p></article><article><h3>Respect the space</h3><p>We plan access and discuss how the work will affect your home.</p></article></div></div></section><section class="container demo-note"><h2>About this example</h2><p>Alder & Flow is a fictional business. It shows how a local service company can explain its work without invented reviews, accreditations or years of experience. Real business details and approved photographs would replace the demonstration content on a client website.</p></section>'''+cta())
pages['services']=('Plumbing help for everyday life.','Explore plumbing repairs, tap and toilet work, and bathroom plumbing.',intro('Our services','For the jobs<br>on your list.','Explore the work we can discuss, then tell us what needs attention in your home.')+'<section class="container service-section">'+cards()+'</section><section class="container editorial"><h2>Not sure which<br>service you need?</h2><div><p>You do not need to diagnose the problem yourself. Describe what you can see, when it started and where it is happening.</p><p>We can discuss whether the job sounds like a repair, replacement or something that needs an inspection first.</p>'+link('contact','Describe the problem →','text-link')+'</div></section>'+cta())
service_data={
'leak-repairs':('Leaks & repairs','A drip worth<br>dealing with.','Help with visible leaks, damp patches and pipework that needs attention.','What we can look at',[('Leaking pipework','Visible joints, waste pipes and connections beneath sinks or around fittings.'),('Unexplained damp','A discussion of where the moisture appears and whether a plumbing inspection is a sensible next step.'),('Everyday repairs','Loose connections and worn fittings that can affect how a kitchen or bathroom works.')],'Tell us where the leak is, when you first noticed it and whether water is still escaping. If it is safe to do so, isolate the affected water supply while arranging help.'),
 'taps-and-toilets':('Taps & toilets','Small fittings.<br>A noticeable difference.','Discuss repairs and replacements for the fittings you use every day.','Common jobs',[('Dripping taps','Checking worn components and discussing whether repair or replacement makes sense.'),('Running toilets','Looking at flush mechanisms, filling problems and visible leaks around the toilet.'),('Replacement fittings','Checking compatibility and access before fitting a new tap, basin or toilet.')],'Mention what the fitting is doing, any make or model you know, and whether you have already bought replacement parts.'),
 'bathroom-plumbing':('Bathroom plumbing','Make room<br>for a better bathroom.','Plumbing support for planned changes, replacement fittings and a bathroom refresh.','Planning the plumbing',[('Basins & fittings','Discuss the basin, taps and connections you want to change.'),('Baths & showers','Review the plumbing requirements, access and compatibility of your proposed fittings.'),('Pipework planning','Talk through what a layout change may involve before you commit to a full refurbishment.')],'Share a short outline of the changes you want, whether the layout will stay the same, and whether other trades are already involved.')}
for key,(label,title,lead,sub,items,prep) in service_data.items():
 content=intro(label,title,lead)+'<section class="container service-detail"><div><p class="eyebrow">'+sub+'</p><h2>Start with<br>the details.</h2>'+''.join('<article><h3>'+h+'</h3><p>'+p+'</p></article>' for h,p in items)+'</div><aside class="job-note"><span class="eyebrow">Before you enquire</span><h2>What helps<br>us understand?</h2><p>'+prep+'</p>'+link('contact','Tell us about the job ↗','button')+'</aside></section><section class="how container"><div class="section-heading"><h2>What happens next.</h2></div>'+steps()+'</section>'+cta()
 pages[key]=(label+' in south-west London',lead,content)
pages['areas']=('Local plumbing in south-west London.','Example coverage areas for a local plumbing business.',intro('Areas we cover','A local service.<br>A familiar patch.','This example is built around south-west London. Send your postcode when you enquire so coverage can be checked.')+'''<section class="container area-layout"><div class="area-art" aria-label="Illustrative service area, not a street map"><svg viewBox="0 0 600 450" aria-hidden="true"><path class="river" d="M-20 90C130 20 155 220 300 160S460 210 630 70"/><path d="M-20 270L620 100M100-20L470 470M-20 410L620 235M200-20L70 470M430-20L310 470"/><circle cx="315" cy="245" r="115"/><circle class="pin" cx="315" cy="245" r="13"/></svg><span>South-west London</span><small>Illustrative service area</small></div><div><p class="eyebrow">Example coverage</p><h2>Close enough<br>to know the area.</h2><ul class="area-list"><li>Wimbledon</li><li>Raynes Park</li><li>Morden</li><li>New Malden</li><li>Kingston upon Thames</li><li>Surbiton</li></ul><p>Nearby but not on the list? Include your postcode and describe the job. On a live website, the business would confirm whether it can help.</p>'''+link('contact','Ask about your postcode →','text-link')+'</div></section>'+cta())
pages['faq']=('Your plumbing questions, answered.','Practical answers about enquiries, visits, fittings and this demonstration website.',intro('Common questions','A few things<br>worth knowing.','Useful information before you enquire, whether you have a repair in mind or a bigger change to plan.')+'<section class="container faq-page">'+faqs()+'</section>'+cta())
pages['contact']=('Tell us about your plumbing job.','Try the demonstration enquiry form and contact options.',intro('Get in touch','What needs<br>sorting?','A few details are enough to start a conversation. Try the form to see how a straightforward enquiry works.')+'''<section class="container contact-grid"><div class="contact-information"><p class="eyebrow">Alder & Flow</p><h2>Let’s start<br>with your home.</h2><p>Example service area:<br>Wimbledon and south-west London</p><div class="contact-actions"><button class="button" data-contact="Call">Call the team ↗</button><button class="button outline" data-contact="WhatsApp">Message on WhatsApp ↗</button></div><p class="small">These are demonstration contact buttons. They do not call or message a real business.</p><div class="contact-hours"><span>Example opening hours</span><p>Monday to Friday · 8am to 6pm<br>Saturday · By arrangement</p></div></div><form id="demo-enquiry" class="contact-form"><p class="eyebrow">Try the enquiry form</p><p class="form-disclosure">Demo only. Please use made-up details. Nothing is sent or saved.</p><div class="form-row"><label>Your name<input name="name" autocomplete="off" required maxlength="100" placeholder="Alex Taylor"></label><label>Email<input name="email" type="email" autocomplete="off" required maxlength="160" placeholder="alex@example.com"></label></div><label>Postcode <span>(optional)</span><input name="postcode" autocomplete="off" maxlength="12" placeholder="e.g. SW19"></label><label>What can we help with?<select name="service"><option>Leaks & repairs</option><option>Taps & toilets</option><option>Bathroom plumbing</option><option>Something else</option></select></label><label>Tell us a little about the job<textarea name="message" required rows="4" maxlength="1800" placeholder="What is happening, and where?"></textarea></label><button class="button" type="submit">Request a callback <span>↗</span></button><p id="form-result" role="status" hidden></p><p class="small">This form demonstrates the layout and validation. A live client site would send the enquiry to the business.</p></form></section>''')
pages['privacy']=('Privacy & demonstration information.','How the ICE WIND demonstration website handles contact forms and illustrative content.',intro('Privacy & demo information','An example.<br>Clear boundaries.','This is a website example by ICE WIND. Alder & Flow is fictional and does not provide plumbing services.')+'''<section class="container prose"><h2>Contact forms and buttons</h2><p>The demonstration form checks the fields in your browser. It does not send or store the details you enter. Please use made-up information when trying it. The call and WhatsApp buttons open a demonstration notice rather than contacting anyone.</p><h2>Illustrative business information</h2><p>The brand, service descriptions, opening hours and coverage areas are illustrative. No customer reviews, trade memberships or professional registrations are claimed.</p><h2>Photography</h2><p>The bathroom photograph is by Clay Banks on Unsplash, used under the Unsplash License. It illustrates the website design and is not presented as a project completed by Alder & Flow.</p><h2>Hosting and fonts</h2><p>The hosting provider receives the technical information needed to serve a page, such as the request address and IP address. Google Fonts is used for typography. This demonstration does not load marketing analytics or set tracking cookies.</p><h2>ICE WIND enquiries</h2><p>To discuss your own website, return to the Limited Offer page. Enquiries made there are covered by the ICE WIND Privacy Notice.</p><a href="/privacy/" class="text-link">Read ICE WIND’s Privacy Notice →</a></section>''')
assert len(pages)==10
for key,(title,desc,body) in pages.items():
 canonical='https://icewind.uk'+base+urls[key]
 nav=''.join(link(k,n,'active' if key==k else '') for k,n in [('services','Services'),('about','About us'),('areas','Our area'),('faq','FAQs')])
 footerlinks=''.join(link(k) for k in urls if k!='home')
 schema=json.dumps({'@context':'https://schema.org','@type':'WebPage','name':title,'url':canonical,'description':desc,'isPartOf':{'@id':'https://icewind.uk'+base},'publisher':{'@id':'https://icewind.uk/#organization'}})
 htmlout=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Alder &amp; Flow · ICE WIND example</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="robots" content="noindex,nofollow,noarchive"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="Alder &amp; Flow · A £499 website example"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://icewind.uk/assets/offer-demo/bathroom.jpg"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="Alder &amp; Flow · ICE WIND example"><meta name="twitter:description" content="{html.escape(desc,quote=True)}"><meta name="twitter:image" content="https://icewind.uk/assets/offer-demo/bathroom.jpg"><meta name="theme-color" content="#153c34"><link rel="icon" type="image/svg+xml" href="/assets/offer-demo/mark.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Serif+Display:ital@0;1&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/offer-demo/style.css?v=20261102a">{org}<script type="application/ld+json">{schema}</script></head><body><a class="skip" href="#main">Skip to content</a><div class="demo-bar"><span>ICE WIND website example <b>10 pages · £499 package</b></span><a href="/limitedoffer/#included">Back to the offer ↗</a></div><header class="site-header"><div class="container nav"><a class="brand" href="{base}" aria-label="Alder and Flow home">{icon}<span>alder <i>&amp;</i> flow<small>HOME PLUMBING</small></span></a><button class="menu-toggle" aria-controls="navigation" aria-expanded="false">Menu <span>☰</span></button><nav id="navigation" aria-label="Main navigation">{nav}{link('contact','Get in touch ↗','button')}</nav></div></header><main id="main">{body}</main><footer><div class="container footer-grid"><div><a class="brand footer-brand" href="{base}">{icon}<span>alder <i>&amp;</i> flow<small>HOME PLUMBING</small></span></a><p>Practical plumbing.<br>A home that works.</p></div><nav aria-label="All pages">{footerlinks}</nav><div><p class="eyebrow">A website by ICE WIND</p><p>Like what you see?<br>Explore the £499 website package.</p><a class="button light" href="/limitedoffer/#included">Your website could be next ↗</a></div></div><div class="container footer-bottom"><span>Demonstration website · Fictional business · No real bookings</span><span>Photography: Clay Banks / Unsplash</span></div></footer><dialog id="contact-preview"><button class="dialog-close" aria-label="Close contact preview">×</button><p class="eyebrow">Contact preview</p><h2 id="contact-preview-title">A direct way to get in touch.</h2><p id="contact-preview-copy"></p><button class="button dialog-done">Back to the example</button></dialog><script src="/assets/offer-demo/app.js?v=20261102a" defer></script></body></html>'''
 path=root/('examples/plumbing/'+urls[key]+'index.html');path.parent.mkdir(parents=True,exist_ok=True);path.write_text(htmlout)
print('Built 10 distinct demonstration pages.')
